class Solution {
public:
    int buyChoco(vector<int>& prices, int money) {
        int a = INT_MAX, b = INT_MAX;
        for (int i = 0; i < (int)prices.size(); i++) {
            if (prices[i] < a) {
                b = a;
                a = prices[i];
            } else if (prices[i] < b) {
                b = prices[i];
            }
        }
        return a + b <= money ? money - a - b : money;
    }
};
